import React, { useState, useEffect } from 'react';
import i18n from 'i18next';

// Define translations with all your provided texts
const resources = {
  en: {
    translation: {
      "app_title": "Fertilizer Recommendation System",
      "app_header": "RECOMMENDING BEST FERTILIZER FOR YOUR CROP",
      "change_language": "Change Language",
      "temperature_label": "Temperature:",
      "humidity_label": "Humidity:",
      "moisture_label": "Moisture:",
      "soil_type_label": "Soil Type:",
      "crop_type_label": "Crop Type:",
      "nitrogen_label": "Nitrogen:",
      "potassium_label": "Potassium:",
      "phosphorous_label": "Phosphorous:",
      "predict_button": "Predict",
      "result_header": "Recommended Fertilizer For Your Crop IS:",
      "default_result": "Fill the form and click 'Predict'",
      "language_en": "English",
      "language_pa": "ਪੰਜਾਬੀ",
      "language_hi": "हिन्दी",
      "soil_black": "Black",
      "soil_clayey": "Clayey",
      "soil_loamy": "Loamy",
      "soil_sandy": "Sandy",
      "soil_red": "Red",
      "crop_barley": "Barley",
      "crop_maize": "Maize",
      "crop_wheat": "Wheat",
      "crop_rice": "Rice",
      "crop_cotton": "Cotton",
      "enter_app": "Enter Application"
    }
  },
  pa: {
    translation: {
      "app_title": "ਖਾਦ ਦੀ ਸਿਫ਼ਾਰਸ਼ ਪ੍ਰਣਾਲੀ",
      "app_header": "ਤੁਹਾਡੀ ਫਸਲ ਲਈ ਸਭ ਤੋਂ ਵਧੀਆ ਖਾਦ ਦੀ ਸਿਫਾਰਸ਼ ਕਰ ਰਿਹਾ ਹੈ",
      "change_language": "ਭਾਸ਼ਾ ਬਦਲੋ",
      "temperature_label": "ਤਾਪਮਾਨ:",
      "humidity_label": "ਨਮੀ:",
      "moisture_label": "ਨਮੀ:",
      "soil_type_label": "ਮਿੱਟੀ ਦੀ ਕਿਸਮ:",
      "crop_type_label": "ਫਸਲ ਦੀ ਕਿਸਮ:",
      "nitrogen_label": "ਨਾਈਟ੍ਰੋਜਨ:",
      "potassium_label": "ਪੋਟਾਸ਼ੀਅਮ:",
      "phosphorous_label": "ਫਾਸਫੋਰਸ:",
      "predict_button": "ਅਨੁਮਾਨ ਲਗਾਓ",
      "result_header": "ਤੁਹਾਡੀ ਫਸਲ ਲਈ ਸਿਫਾਰਸ਼ ਕੀਤੀ ਖਾਦ ਹੈ:",
      "default_result": "ਫਾਰਮ ਭਰੋ ਅਤੇ 'ਅਨੁਮਾਨ ਲਗਾਓ' 'ਤੇ ਕਲਿੱਕ ਕਰੋ",
      "language_en": "ਅੰਗਰੇਜ਼ੀ",
      "language_pa": "ਪੰਜਾਬੀ",
      "language_hi": "ਹਿੰਦੀ",
      "soil_black": "ਕਾਲੀ",
      "soil_clayey": "ਚੀਕਣੀ",
      "soil_loamy": "ਰੇਤਲੀ",
      "soil_sandy": "ਰੇਤਲੀ",
      "soil_red": "ਲਾਲ",
      "crop_barley": "ਜੌਂ",
      "crop_maize": "ਮੱਕੀ",
      "crop_wheat": "ਕਣਕ",
      "crop_rice": "ਚੌਲ",
      "crop_cotton": "ਕਪਾਹ",
      "enter_app": "ਐਪਲੀਕੇਸ਼ਨ ਦਾਖਲ ਕਰੋ"
    }
  },
  hi: {
    translation: {
      "app_title": "उर्वरक सिफारिश प्रणाली",
      "app_header": "आपकी फसल के लिए सर्वोत्तम उर्वरक की सिफारिश",
      "change_language": "भाषा बदलें",
      "temperature_label": "तापमान:",
      "humidity_label": "आर्द्रता:",
      "moisture_label": "नमी:",
      "soil_type_label": "मिट्टी का प्रकार:",
      "crop_type_label": "फसल का प्रकार:",
      "nitrogen_label": "नाइट्रोजन:",
      "potassium_label": "पोटेशियम:",
      "phosphorous_label": "फास्फोरस:",
      "predict_button": "भविष्यवाणी करें",
      "result_header": "आपकी फसल के लिए अनुशंसित उर्वरक है:",
      "default_result": "फ़ॉर्म भरें और 'भविष्यवाणी करें' पर क्लिक करें",
      "language_en": "अंग्रेज़ी",
      "language_pa": "ਪੰਜਾਬੀ",
      "language_hi": "हिन्दी",
      "soil_black": "काली",
      "soil_clayey": "चिकनी",
      "soil_loamy": "दोमट",
      "soil_sandy": "रेतीली",
      "soil_red": "लाल",
      "crop_barley": "जौ",
      "crop_maize": "मक्का",
      "crop_wheat": "गेहूं",
      "crop_rice": "चावल",
      "crop_cotton": "कपास",
      "enter_app": "एप्लिकेशन दर्ज करें"
    }
  }
};

i18n.init({
  compatibilityJSON: 'v3',
  resources,
  lng: 'en',
  fallbackLng: 'en',
  interpolation: { escapeValue: false }
});

const soilTypeMapping = { Black: 0, Clayey: 1, Loamy: 2, Sandy: 3, Red: 4 };
const cropTypeMapping = { Barley: 0, Maize: 1, Wheat: 2, Rice: 3, Cotton: 4 };

const App = () => {
  const [currentLanguage, setCurrentLanguage] = useState(i18n.language);
  const [isFormVisible, setIsFormVisible] = useState(false);
  const [inputs, setInputs] = useState({
    temperature: '',
    humidity: '',
    moisture: '',
    soilType: 'Black',
    cropType: 'Barley',
    nitrogen: '',
    potassium: '',
    phosphorous: '',
  });
  const [result, setResult] = useState(i18n.t('default_result'));
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const handleLanguageChange = (lng) => {
      setCurrentLanguage(lng);
      setResult(i18n.t('default_result'));
    };
    i18n.on('languageChanged', handleLanguageChange);
    return () => i18n.off('languageChanged', handleLanguageChange);
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setInputs(prev => ({ ...prev, [name]: value }));
  };

  const handleLanguageChange = (e) => {
    const newLng = e.target.value;
    i18n.changeLanguage(newLng);
  };

  const handlePredict = async () => {
    setIsLoading(true);
    setResult("Loading...");

    const dataToSend = {
      ...inputs,
      soilType: soilTypeMapping[inputs.soilType],
      cropType: cropTypeMapping[inputs.cropType]
    };

    const apiUrl = 'http://127.0.0.1:5000/predict';

    try {
      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(dataToSend),
      });

      if (!response.ok) throw new Error('Network response was not ok');
      const data = await response.json();
      setResult(data.recommendation);
    } catch (error) {
      console.error('Fetch operation problem:', error);
      setResult("Error: Could not get a recommendation.");
    } finally {
      setIsLoading(false);
    }
  };

  const inputClass = "w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-green-500";
  const labelClass = "text-sm md:text-base font-semibold text-gray-700";
  const buttonClass = "bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-12 rounded-full transition-colors duration-300 shadow-lg text-lg focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const renderFormUI = () => (
    <>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-4">
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('temperature_label')}</label>
            <input type="number" name="temperature" value={inputs.temperature} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('humidity_label')}</label>
            <input type="number" name="humidity" value={inputs.humidity} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('moisture_label')}</label>
            <input type="number" name="moisture" value={inputs.moisture} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('nitrogen_label')}</label>
            <input type="number" name="nitrogen" value={inputs.nitrogen} onChange={handleInputChange} className={inputClass} />
          </div>
        </div>

        <div className="space-y-4">
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('soil_type_label')}</label>
            <select name="soilType" value={inputs.soilType} onChange={handleInputChange} className={inputClass}>
              <option value="Black">{i18n.t('soil_black')}</option>
              <option value="Clayey">{i18n.t('soil_clayey')}</option>
              <option value="Loamy">{i18n.t('soil_loamy')}</option>
              <option value="Sandy">{i18n.t('soil_sandy')}</option>
              <option value="Red">{i18n.t('soil_red')}</option>
            </select>
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('crop_type_label')}</label>
            <select name="cropType" value={inputs.cropType} onChange={handleInputChange} className={inputClass}>
              <option value="Barley">{i18n.t('crop_barley')}</option>
              <option value="Maize">{i18n.t('crop_maize')}</option>
              <option value="Wheat">{i18n.t('crop_wheat')}</option>
              <option value="Rice">{i18n.t('crop_rice')}</option>
              <option value="Cotton">{i18n.t('crop_cotton')}</option>
            </select>
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('potassium_label')}</label>
            <input type="number" name="potassium" value={inputs.potassium} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('phosphorous_label')}</label>
            <input type="number" name="phosphorous" value={inputs.phosphorous} onChange={handleInputChange} className={inputClass} />
          </div>
        </div>
      </div>

      <div className="mt-8 flex justify-center">
        <button onClick={handlePredict} disabled={isLoading} className={buttonClass}>
          {isLoading ? 'Predicting...' : i18n.t('predict_button')}
        </button>
      </div>
    </>
  );

  const renderHomeScreen = () => (
    <div className="flex flex-col items-center justify-center min-h-[calc(100vh-100px)] p-4 md:p-8">
      <div className="text-center mb-10">
        <h1 className="text-6xl sm:text-7xl font-extrabold text-white tracking-wider drop-shadow-lg">
          KHARIF
        </h1>
        <p className="mt-2 text-xl sm:text-2xl font-medium text-white drop-shadow-lg">
          A Soil Health Recommendations And Fertilizer         </p>
      </div>

      <button onClick={() => setIsFormVisible(true)} className="bg-yellow-500 hover:bg-yellow-600 text-gray-900 font-bold py-3 px-8 rounded-full text-xl transition-all duration-300 shadow-2xl focus:outline-none focus:ring-4 focus:ring-yellow-400 focus:ring-offset-2">
        {i18n.t('enter_app')}
      </button>
    </div>
  );

  return (
    <div className="min-h-screen bg-cover bg-center" style={{ backgroundImage: "url('/adele-payman-2oYMwuFgnTg-unsplash.jpg')" }}>
      <div className="absolute inset-0 bg-black opacity-60"></div>

      <h1 className="relative z-20 text-4xl font-extrabold text-white text-center pt-8 tracking-wider" style={{ textShadow: '2px 2px 4px rgba(0,0,0,0.5)' }}>
        TEAM IOTA Presents
      </h1>

      <div className="relative z-10 flex flex-col items-center justify-center min-h-[calc(100vh-100px)] p-4 md:p-8">
        {isFormVisible ? (
          <>
            <div className="w-full max-w-2xl flex justify-end items-center mb-4 relative z-20">
              <button onClick={() => setIsFormVisible(false)} className="bg-gray-700 hover:bg-gray-800 text-white text-sm font-bold py-2 px-4 rounded-full transition-colors duration-300 shadow-lg mr-2">
                ← Back
              </button>
              <label htmlFor="language-select" className="text-white font-medium hidden md:block mr-2">{i18n.t('change_language')}:</label>
              <select id="language-select" value={currentLanguage} onChange={handleLanguageChange} className="p-2 border border-gray-300 rounded-lg shadow-sm text-gray-700 focus:outline-none focus:ring-2 focus:ring-green-500">
                <option value="en">{i18n.t('language_en')}</option>
                <option value="pa">{i18n.t('language_pa')}</option>
                <option value="hi">{i18n.t('language_hi')}</option>
              </select>
            </div>

            <div className="bg-white rounded-3xl shadow-xl p-6 md:p-12 max-w-2xl w-full">
              <div className="flex justify-center mb-6 border-b pb-4">
                <h2 className="text-2xl font-extrabold text-gray-800 tracking-wide text-center">
                  {i18n.t('app_header')}
                </h2>
              </div>
              {renderFormUI()}
            </div>

            <div className="mt-8 bg-white rounded-3xl shadow-xl p-6 w-full max-w-2xl text-center">
              <h3 className="text-xl md:text-2xl font-bold text-gray-800 mb-2">
                {i18n.t('result_header')}
              </h3>
              <p className="text-3xl md:text-4xl font-extrabold text-green-700">
                {result}
              </p>
            </div>
          </>
        ) : (
          renderHomeScreen()
        )}
      </div>
    </div>
  );
};

export default App;
